create table auth.sessions(id uuid primary key,user_id uuid references auth.users(id),created_at timestamptz,updated_at timestamptz,not_after timestamptz,user_agent text,ip inet);
create function pg_temp.ok(v boolean,m text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'ASSERT: %',m;end if;end $$;
create function pg_temp.refused(q text,c text default '42501') returns void language plpgsql as $$ begin begin execute q; exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'not refused: %',q;end $$;
