select pg_temp.ok(not has_function_privilege('authenticated','public.record_mfa_recovery_request(uuid,uuid,uuid,uuid,uuid,text)','execute'),'direct client cannot spoof subject');
select pg_temp.ok(not has_function_privilege('service_role','public.record_mfa_recovery_request(uuid,uuid,uuid,uuid,uuid,text)','execute'),'reader cannot mutate');
select pg_temp.ok(has_function_privilege('human_action_writer','public.record_mfa_recovery_request(uuid,uuid,uuid,uuid,uuid,text)','execute'),'restricted writer can submit');
